import{_ as a,o as n,c as m,a4 as p}from"./chunks/framework.DAD9IEko.js";const g=JSON.parse('{"title":"通信协议 COM-01 ~ COM-09","description":"","frontmatter":{"title":"通信协议 COM-01 ~ COM-09","date":"2026-07-02T00:00:00.000Z","section":"电机控制","chapter":"learning-workspace","chapterTitle":"学习工作区","category":"学习工作区","tags":["imported"],"source":"motor","sourcePath":"learning-workspace/lessons/0012-communication-protocols.html","status":"learning","visibility":"public","summary":"Imported from learning-workspace/lessons/0012-communication-protocols.html","chapterOrder":5,"navGroup":"入门与索引","navGroupOrder":10},"headers":[],"relativePath":"content/motor/learning-workspace/lessons/0012-communication-protocols.md","filePath":"content/motor/learning-workspace/lessons/0012-communication-protocols.md","lastUpdated":1783181958000}'),t={name:"content/motor/learning-workspace/lessons/0012-communication-protocols.md"};function l(i,s,e,r,c,o){return n(),m("div",null,[...s[0]||(s[0]=[p('<p>返回知识库 COM-01~09 通信协议 0/9</p><p>学习模块 01CAN基础 02CAN-FD 03CAN STM32实战 04CAN仿真 05Modbus协议 06EtherCAT 07协议对比选型 08AUTOSAR架构 09工业通信PHY</p><h1 id="通信协议-com-01-com-09" tabindex="-1">通信协议 COM-01 ~ COM-09 <a class="header-anchor" href="#通信协议-com-01-com-09" aria-label="Permalink to &quot;通信协议 COM-01 ~ COM-09&quot;">​</a></h1><p>电机控制系统的信息动脉 -- 从CAN总线到EtherCAT实时以太网，系统掌握工业通信核心技术。涵盖CAN/Modbus/EtherCAT协议原理、STM32实战、AUTOSAR架构及PHY层设计等9大模块。</p><p>9 个模块18 道练习进阶级预计 8-10 小时</p><p>COM-01</p><h2 id="can基础" tabindex="-1">CAN基础 <a class="header-anchor" href="#can基础" aria-label="Permalink to &quot;CAN基础&quot;">​</a></h2><p>核心概念▼</p><h4 id="can帧结构" tabindex="-1">CAN帧结构 <a class="header-anchor" href="#can帧结构" aria-label="Permalink to &quot;CAN帧结构&quot;">​</a></h4><p>标准帧（CAN 2.0A）：11位标识符，最大数据8字节。扩展帧（CAN 2.0B）：29位标识符。帧类型：数据帧、远程帧、错误帧、过载帧。数据帧含SOF、仲裁场、控制场、数据场、CRC场、ACK场、EOF。</p><h4 id="仲裁机制" tabindex="-1">仲裁机制 <a class="header-anchor" href="#仲裁机制" aria-label="Permalink to &quot;仲裁机制&quot;">​</a></h4><p>多节点同时发送时，通过&quot;线与&quot;机制仲裁。显性电平（0）覆盖隐性电平（1），标识符越小优先级越高。发送隐性位但检测到显性位的节点自动退出，实现非破坏性仲裁。</p><h4 id="位定时" tabindex="-1">位定时 <a class="header-anchor" href="#位定时" aria-label="Permalink to &quot;位定时&quot;">​</a></h4><p>位时间分为4段：同步段(Sync)、传播段(Prop)、相位缓冲段1(Phase1)、相位缓冲段2(Phase2)。通过位定时参数配置波特率，采样点通常在85%~90%位置。需根据总线长度和传播延迟计算。</p><h4 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h4><p>5种错误类型：位错误、填充错误、CRC错误、格式错误、ACK错误。每个节点维护TEC（发送错误计数）和REC（接收错误计数），决定错误状态：主动错误(0~127)、被动错误(128~255)、总线关闭(&gt;255)。</p><p>电机控制关联：CAN是电机驱动器与上位控制器通信的标准总线。伺服驱动器的位置/速度/转矩指令、编码器反馈、故障诊断均通过CAN传输。理解仲裁机制对多轴系统消息优先级设计至关重要。</p><p>𝟗关键公式▼</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>f</mi><mrow><mi>C</mi><mi>A</mi><mi>N</mi><mi>c</mi><mi>l</mi><mi>k</mi></mrow></msub><mrow><mi>B</mi><mi>R</mi><mi>P</mi><mo>×</mo><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>2</mn><mo stretchy="false">)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">f_{baud} = \\frac{f_{CANclk}}{BRP \\times (1 + TSEG1 + TSEG2)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3074em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">2</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span><span class="mord mathnormal mtight">A</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>CAN波特率计算。BRP为分频器，TSEG1/TSEG2为位时间段。例：36MHz时钟，BRP=4，TSEG1=9，TSEG2=4，波特率=500kbps。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>采样点</mtext><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn></mrow><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>2</mn></mrow></mfrac><mo>×</mo><mn>100</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">\\text{采样点} = \\frac{1 + TSEG1}{1 + TSEG1 + TSEG2} \\times 100\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">采样点</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">100%</span></span></span></span></span><p>采样点位置。推荐范围85%~90%。TSEG1=9, TSEG2=4时采样点=71.4%，偏低；TSEG1=13, TSEG2=2时采样点=87.5%，推荐。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>t</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><mn>2</mn><mo>×</mo><mfrac><msub><mi>L</mi><mrow><mi>b</mi><mi>u</mi><mi>s</mi></mrow></msub><msub><mi>v</mi><mrow><mi>s</mi><mi>i</mi><mi>g</mi><mi>n</mi><mi>a</mi><mi>l</mi></mrow></msub></mfrac></mrow><annotation encoding="application/x-tex">t_{prop} = 2 \\times \\frac{L_{bus}}{v_{signal}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9012em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3324em;vertical-align:-0.9721em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">na</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>传播延迟。L_bus为总线长度，v_signal约5ns/m（光速的2/3）。10m总线传播延迟约100ns，500kbps位时间2us，传播段需覆盖此延迟。</p><p>练习题 (2)▼</p><p>简单CAN总线仲裁机制的工作原理是什么？为什么说它是&quot;非破坏性&quot;的？标准帧和扩展帧的标识符长度分别是多少？查看参考参考解答</p><p>**仲裁原理：**CAN总线采用&quot;线与&quot;机制，显性电平（逻辑0）可以覆盖隐性电平（逻辑1）。当多个节点同时发送时，每个节点在发送标识符位的同时监测总线电平。如果发送隐性位但检测到显性位，说明有更高优先级的消息正在发送，该节点自动退出仲裁。</p><p>**&quot;非破坏性&quot;含义：**赢得仲裁的消息不会被破坏，可以继续完整发送，无需重传。这与CSMA/CD（以太网碰撞后全部重传）不同。</p><p><strong>标识符长度：</strong></p><ul><li><p>标准帧（CAN 2.0A）：11位标识符，范围0x000~0x7FF（2048个）</p></li><li><p>扩展帧（CAN 2.0B）：29位标识符，范围0x00000000~0x1FFFFFFF（超5亿个）</p></li></ul><p>标识符数值越小，优先级越高。电机控制中通常将紧急故障消息分配最低ID。</p><p>自评：掌握部分未掌握 中等CAN位定时中，采样点位置如何影响通信可靠性？给定APB1时钟36MHz，要求波特率1Mbps，采样点87.5%，计算BRP、TSEG1、TSEG2。查看参考参考解答</p><p>**采样点影响：**采样点过早可能采样到信号跳变区域，导致误判；过晚则减少重同步裕量。CiA推荐采样点在87.5%位置，兼顾信号稳定性和同步能力。</p><p><strong>计算过程：</strong></p><ol><li><p>总时间份额 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi><mo>=</mo><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">N = 1 + TSEG1 + TSEG2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">2</span></span></span></span></p></li><li><p>采样点87.5%：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn></mrow><mi>N</mi></mfrac><mo>=</mo><mn>0.875</mn></mrow><annotation encoding="application/x-tex">\\frac{1+TSEG1}{N} = 0.875</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2173em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8723em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span><span class="mord mathnormal mtight">G</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.875</span></span></span></span>，即 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>0.875</mn><mi>N</mi></mrow><annotation encoding="application/x-tex">1+TSEG1 = 0.875N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.875</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span></p></li><li><p>取N=16：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>14</mn></mrow><annotation encoding="application/x-tex">1+TSEG1=14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">14</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>13</mn></mrow><annotation encoding="application/x-tex">TSEG1=13</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">13</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>2</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">TSEG2=2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span></p></li><li><p>波特率1Mbps：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub><mo>=</mo><msub><mi>f</mi><mrow><mi>c</mi><mi>l</mi><mi>k</mi></mrow></msub><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mi>B</mi><mi>R</mi><mi>P</mi><mo>×</mo><mi>N</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">f_{baud}=f_{clk}/(BRP \\times N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mi>R</mi><mi>P</mi><mo>=</mo><mn>36</mn><mtext>MHz</mtext><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>1</mn><mtext>Mbps</mtext><mo>×</mo><mn>16</mn><mo stretchy="false">)</mo><mo>=</mo><mn>2.25</mn></mrow><annotation encoding="application/x-tex">BRP = 36\\text{MHz}/(1\\text{Mbps}\\times 16) = 2.25</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">36</span><span class="mord text"><span class="mord">MHz</span></span><span class="mord">/</span><span class="mopen">(</span><span class="mord">1</span><span class="mord text"><span class="mord">Mbps</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">16</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.25</span></span></span></span></p></li><li><p>BRP必须为整数，取BRP=2：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub><mo>=</mo><mn>36</mn><mtext>M</mtext><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>2</mn><mo>×</mo><mn>16</mn><mo stretchy="false">)</mo><mo>=</mo><mn>1.125</mn><mtext>Mbps</mtext></mrow><annotation encoding="application/x-tex">f_{baud}=36\\text{M}/(2\\times16)=1.125\\text{Mbps}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">36</span><span class="mord text"><span class="mord">M</span></span><span class="mord">/</span><span class="mopen">(</span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">16</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">1.125</span><span class="mord text"><span class="mord">Mbps</span></span></span></span></span>，偏差12.5%不可接受</p></li><li><p>取N=8：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">1+TSEG1=7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">TSEG1=6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>2</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">TSEG2=1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mi>R</mi><mi>P</mi><mo>=</mo><mn>36</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>1</mn><mo>×</mo><mn>8</mn><mo stretchy="false">)</mo><mo>=</mo><mn>4.5</mn></mrow><annotation encoding="application/x-tex">BRP=36/(1\\times8)=4.5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">36/</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">8</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.5</span></span></span></span>，取BRP=4，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub><mo>=</mo><mn>1.125</mn><mtext>Mbps</mtext></mrow><annotation encoding="application/x-tex">f_{baud}=1.125\\text{Mbps}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">1.125</span><span class="mord text"><span class="mord">Mbps</span></span></span></span></span></p></li><li><p>更好方案：使用36MHz整除，N=9，BRP=4，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub><mo>=</mo><mn>1</mn><mtext>Mbps</mtext></mrow><annotation encoding="application/x-tex">f_{baud}=1\\text{Mbps}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mord text"><span class="mord">Mbps</span></span></span></span></span>。<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>+</mo><mi>T</mi><mi>S</mi><mi>E</mi><mi>G</mi><mn>1</mn><mo>=</mo><mn>0.875</mn><mo>×</mo><mn>9</mn><mo>=</mo><mn>7.875</mn></mrow><annotation encoding="application/x-tex">1+TSEG1=0.875\\times9=7.875</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal">G</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.875</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">9</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7.875</span></span></span></span>，取TSEG1=7，TSEG2=1，采样点=8/9=88.9%</p></li></ol><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-02</p><h2 id="can-fd" tabindex="-1">CAN-FD <a class="header-anchor" href="#can-fd" aria-label="Permalink to &quot;CAN-FD&quot;">​</a></h2><p>核心概念▼</p><h4 id="灵活数据率" tabindex="-1">灵活数据率 <a class="header-anchor" href="#灵活数据率" aria-label="Permalink to &quot;灵活数据率&quot;">​</a></h4><p>CAN-FD（Flexible Data-rate）在仲裁段使用经典CAN波特率，在数据段切换到更高波特率（最高5~8Mbps）。BRS（Bit Rate Switch）位标识是否切换速率，使数据传输效率大幅提升。</p><h4 id="数据长度扩展" tabindex="-1">数据长度扩展 <a class="header-anchor" href="#数据长度扩展" aria-label="Permalink to &quot;数据长度扩展&quot;">​</a></h4><p>经典CAN最大8字节，CAN-FD支持0/1/2/3/4/5/6/7/8/12/16/20/24/32/48/64字节。DLC编码扩展：DLC=9~15分别映射到12/16/20/24/32/48/64字节，大幅减少协议开销占比。</p><h4 id="与经典can对比" tabindex="-1">与经典CAN对比 <a class="header-anchor" href="#与经典can对比" aria-label="Permalink to &quot;与经典CAN对比&quot;">​</a></h4><p>相同：帧格式兼容、仲裁机制相同、错误处理一致。不同：数据段可变速率、数据长度扩展至64字节、不支持远程帧、CRC场扩展至17/21位、填充位规则不同（固定填充位FSB）。</p><h4 id="crc改进" tabindex="-1">CRC改进 <a class="header-anchor" href="#crc改进" aria-label="Permalink to &quot;CRC改进&quot;">​</a></h4><p>经典CAN使用15位CRC，CAN-FD使用17位CRC（DLC≤16）或21位CRC（DLC&gt;16），并引入固定填充位（FSB）防止填充位与CRC交互影响，提高数据完整性。</p><p>电机控制关联：CAN-FD在多轴伺服系统中优势明显：64字节数据帧可一次传输多轴位置/电流数据，5Mbps数据段速率将周期从1ms降至200us，满足高速伺服的通信周期需求。</p><p>𝟗关键公式▼</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>吞吐率</mtext><mo>=</mo><mfrac><mrow><mi>D</mi><mo>×</mo><mn>8</mn></mrow><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub></mfrac></mrow><annotation encoding="application/x-tex">\\text{吞吐率} = \\frac{D \\times 8}{T_{frame}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">吞吐率</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3324em;vertical-align:-0.9721em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">8</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>有效数据吞吐率。D为数据字节数，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub></mrow><annotation encoding="application/x-tex">T_{frame}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>为帧总时间。CAN-FD 64字节@5Mbps数据段：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub><mo>≈</mo><mn>140</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T_{frame}\\approx140\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">140</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span>，吞吐率约3.6Mbps。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>η</mi><mo>=</mo><mfrac><mrow><mi>D</mi><mo>×</mo><mn>8</mn></mrow><mrow><mi>D</mi><mo>×</mo><mn>8</mn><mo>+</mo><mtext>overhead</mtext></mrow></mfrac><mo>×</mo><mn>100</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">\\eta = \\frac{D \\times 8}{D \\times 8 + \\text{overhead}} \\times 100\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">overhead</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">8</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">100%</span></span></span></span></span><p>协议效率。经典CAN 8字节：overhead约44位，效率59%。CAN-FD 64字节：overhead约70位，效率88%。数据越长效率越高。</p><p>练习题 (2)▼</p><p>简单CAN-FD的BRS位起什么作用？数据段速率相比经典CAN可以提升多少？查看参考参考解答</p><p>**BRS位作用：**BRS（Bit Rate Switch）位于控制场中，标识该帧的数据段是否使用更高速率。BRS=1时，从BRS位之后到CRC分隔符之前，位速率切换到更高的数据段速率；BRS=0时，整帧使用仲裁段速率（与经典CAN相同）。</p><p><strong>速率提升：</strong></p><ul><li><p>仲裁段：通常500kbps~1Mbps（与经典CAN兼容）</p></li><li><p>数据段：2Mbps、5Mbps，最高可达8Mbps（ISO 11898-1:2015）</p></li><li><p>相比经典CAN最高1Mbps，数据段速率提升2~8倍</p></li><li><p>实际提升取决于总线长度、收发器和EMC约束</p></li></ul><p>**注意：**仲裁段必须保持较低速率以确保多节点仲裁正确工作，只有点对点数据传输段才可加速。</p><p>自评：掌握部分未掌握 中等CAN-FD相比经典CAN在协议效率和实时性上有哪些提升？计算64字节数据用经典CAN和CAN-FD分别传输所需的总线时间。查看参考参考解答</p><p>**协议效率提升：**经典CAN每帧最多8字节，64字节需8帧，每帧overhead约44位。CAN-FD单帧64字节，overhead约70位。</p><p><strong>总线时间计算：</strong></p><p>经典CAN（500kbps）：8帧 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span> (44+64)位 = 864位，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mo>=</mo><mn>864</mn><mi mathvariant="normal">/</mi><mn>500</mn><mtext>k</mtext><mo>=</mo><mn>1.728</mn><mtext>ms</mtext></mrow><annotation encoding="application/x-tex">T = 864/500\\text{k} = 1.728\\text{ms}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">864/500</span><span class="mord text"><span class="mord">k</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.728</span><span class="mord text"><span class="mord">ms</span></span></span></span></span></p><p>CAN-FD（仲裁500kbps，数据5Mbps）：仲裁段约40位@500kbps=80us，数据段约(64<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span>8+30)位@5Mbps=108us，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mo>≈</mo><mn>188</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T \\approx 188\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">188</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span></p><p><strong>提升倍数：</strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1.728</mn><mtext>ms</mtext><mi mathvariant="normal">/</mi><mn>188</mn><mi>μ</mi><mi>s</mi><mo>≈</mo><mn>9.2</mn></mrow><annotation encoding="application/x-tex">1.728\\text{ms}/188\\mu s \\approx 9.2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1.728</span><span class="mord text"><span class="mord">ms</span></span><span class="mord">/188</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">9.2</span></span></span></span>倍</p><p><strong>实时性提升：</strong></p><ol><li><p>单帧传输减少仲裁次数和帧间隔</p></li><li><p>数据段高速率缩短传输时间</p></li><li><p>通信周期从1ms级降至100~200us级</p></li><li><p>多轴伺服系统可在更短周期内完成所有轴的数据交换</p></li></ol><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-03</p><h2 id="can-stm32实战" tabindex="-1">CAN STM32实战 <a class="header-anchor" href="#can-stm32实战" aria-label="Permalink to &quot;CAN STM32实战&quot;">​</a></h2><p>核心概念▼</p><h4 id="bxcan配置" tabindex="-1">bxCAN配置 <a class="header-anchor" href="#bxcan配置" aria-label="Permalink to &quot;bxCAN配置&quot;">​</a></h4><p>STM32的bxCAN模块含发送邮箱（3个）和接收FIFO（2个）。配置步骤：使能CAN时钟、配置GPIO复用、设置位定时参数（BRP/TSEG1/TSEG2）、配置工作模式（正常/环回/静默）、使能中断。</p><h4 id="发送邮箱" tabindex="-1">发送邮箱 <a class="header-anchor" href="#发送邮箱" aria-label="Permalink to &quot;发送邮箱&quot;">​</a></h4><p>3个发送邮箱，优先级由标识符或请求顺序决定。发送流程：选择空邮箱、填写标识符/DLC/数据、请求发送（TXRQ位）。发送完成后硬件置位发送完成标志，可触发中断。</p><h4 id="接收fifo与滤波" tabindex="-1">接收FIFO与滤波 <a class="header-anchor" href="#接收fifo与滤波" aria-label="Permalink to &quot;接收FIFO与滤波&quot;">​</a></h4><p>2个接收FIFO，每个3级深度。硬件滤波器（STM32F4有28个）可配置为标识符列表模式或掩码模式。掩码模式：ID&amp;Mask决定哪些位需要匹配。滤波通过的消息存入FIFO，溢出时根据策略丢弃旧消息或新消息。</p><h4 id="中断处理" tabindex="-1">中断处理 <a class="header-anchor" href="#中断处理" aria-label="Permalink to &quot;中断处理&quot;">​</a></h4><p>关键中断：发送完成（TX）、接收FIFO非空（RX）、错误警告（EWG）、总线关闭（BUSOFF）。中断中应快速读取FIFO数据或设置发送标志，耗时处理放在主循环。FIFO溢出中断需特别处理防止消息丢失。</p><p>电机控制关联：STM32是电机驱动器主流MCU，bxCAN是驱动器与上位机/PLC通信的核心外设。滤波器配置决定哪些消息被接收，影响CPU负载；中断优先级需高于一般外设低于PWM紧急保护。</p><p>练习题 (2)▼</p><p>简单STM32 bxCAN有几个发送邮箱？接收FIFO有几个？每个FIFO多深？查看参考参考解答</p><p>**发送邮箱：**3个。可以同时准备3条消息等待发送。优先级策略可选：按标识符优先级或按请求顺序。当3个邮箱都满时，新发送请求会被拒绝。</p><p>**接收FIFO：**2个（FIFO0和FIFO1），每个3级深度（可存3条消息）。</p><ul><li><p>FIFO0和FIFO1可分别关联不同的滤波器组</p></li><li><p>当FIFO满时，新消息根据FIFO锁定配置决定丢弃策略</p></li><li><p>FIFO0和FIFO1可分别映射到不同中断</p></li></ul><p>**典型配置：**将高优先级消息（故障/紧急指令）路由到FIFO0并设高优先级中断，普通消息路由到FIFO1。</p><p>自评：掌握部分未掌握 中等STM32 CAN滤波器的掩码模式如何工作？如果要接收ID范围0x100~0x10F的消息，如何配置ID和Mask？查看参考参考解答</p><p>**掩码模式原理：**接收消息的ID与滤波器ID按位比较，只比较Mask为1的位。即：(received_ID &amp; Mask) == (filter_ID &amp; Mask) 时通过。</p><p><strong>配置0x100~0x10F：</strong></p><ol><li><p>分析范围：0x100 = 0b1_0000_0000，0x10F = 0b1_0000_1111</p></li><li><p>高7位固定为0b1_0000_0，低4位可变（0~F）</p></li><li><p>ID = 0x100（固定位的值）</p></li><li><p>Mask = 0x7F0（高7位和中间位需匹配，低4位不关心）</p></li></ol><p>验证：0x100 &amp; 0x7F0 = 0x100，0x10F &amp; 0x7F0 = 0x100，均匹配。0x110 &amp; 0x7F0 = 0x110 ≠ 0x100，不匹配。</p><p>**注意：**STM32的滤波器寄存器中ID和Mask还包含RTR和IDE位，需一并设置。32位滤波器可同时过滤扩展帧和标准帧。</p><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-04</p><h2 id="can仿真" tabindex="-1">CAN仿真 <a class="header-anchor" href="#can仿真" aria-label="Permalink to &quot;CAN仿真&quot;">​</a></h2><p>核心概念▼</p><h4 id="虚拟can网络" tabindex="-1">虚拟CAN网络 <a class="header-anchor" href="#虚拟can网络" aria-label="Permalink to &quot;虚拟CAN网络&quot;">​</a></h4><p>使用软件模拟CAN总线，无需物理硬件即可开发和测试。Linux下vcan驱动创建虚拟接口，Vector CANoe/CANalyzer提供专业仿真环境。支持消息收发、数据库导入、自动化测试脚本。</p><h4 id="硬件在环-hil" tabindex="-1">硬件在环(HIL) <a class="header-anchor" href="#硬件在环-hil" aria-label="Permalink to &quot;硬件在环(HIL)&quot;">​</a></h4><p>将真实ECU连接到仿真系统，模拟整车环境。CANoe可模拟其他ECU节点、故障注入（断路/短路/错误帧）、总线负载调节。验证ECU在各种工况下的行为。</p><h4 id="测试方法" tabindex="-1">测试方法 <a class="header-anchor" href="#测试方法" aria-label="Permalink to &quot;测试方法&quot;">​</a></h4><p>功能测试：验证消息收发、信号解析、状态机转换。压力测试：高总线负载（&gt;80%）、消息风暴。容错测试：总线断路/短路、节点掉线、错误帧注入。一致性测试：遵循协议规范（ISO 16845）。</p><h4 id="自动化测试" tabindex="-1">自动化测试 <a class="header-anchor" href="#自动化测试" aria-label="Permalink to &quot;自动化测试&quot;">​</a></h4><p>使用CAPL（CANoe脚本）或Python+CAN库编写自动化测试用例。覆盖正常流程、边界条件、异常恢复。集成到CI/CD流水线，每次代码变更自动运行通信测试。</p><p>电机控制关联：电机驱动器CAN通信的可靠性直接影响系统安全。仿真测试可验证：指令丢失时的安全响应、总线关闭后的恢复策略、多轴协同时的消息调度、EMC干扰下的通信鲁棒性。</p><p>练习题 (2)▼</p><p>简单CAN仿真测试中需要覆盖哪些关键场景？查看参考参考解答</p><p><strong>关键测试场景：</strong></p><ol><li><p>**正常通信：**消息收发正确性、信号解析精度、周期稳定性</p></li><li><p>**高负载：**总线负载率&gt;80%时的消息延迟和丢失率</p></li><li><p>**故障注入：**总线断路、CANH/CANL短路、电源掉电、节点离线</p></li><li><p>**错误处理：**错误帧注入后的恢复时间、TEC/REC计数变化、总线关闭恢复</p></li><li><p>**多节点竞争：**仲裁冲突时的优先级正确性、消息顺序</p></li><li><p>**边界条件：**DLC=0/8、极端ID值、连续远程帧</p></li><li><p>**EMC抗扰：**注入共模干扰、差模干扰，验证通信稳定性</p></li><li><p>**安全响应：**通信超时后的安全状态切换、看门狗触发</p></li></ol><p>自评：掌握部分未掌握 中等设计一个电机驱动器CAN通信的HIL测试方案，包含至少5个测试用例。查看参考参考解答</p><p><strong>HIL测试方案：</strong></p><p>**TC1-指令响应：**发送速度指令0~3000rpm，验证驱动器在10ms内响应且实际转速误差≤1%</p><p>**TC2-通信超时：**停止发送指令500ms后，验证驱动器进入安全停机状态（减速至0），超时阈值可配置</p><p>**TC3-总线关闭恢复：**持续注入错误帧使驱动器CAN节点进入Bus-Off，验证128<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span>11位时间后自动恢复通信</p><p>**TC4-多轴协同：**4个驱动器同时在线，1ms周期内完成所有轴的指令下发和状态上传，验证无消息丢失</p><p>**TC5-故障上报：**注入过流/过压/过温故障，验证驱动器在100us内通过CAN发送紧急故障帧（最高优先级ID），并进入保护状态</p><p>**TC6-EMC抗扰：**注入CAN总线共模噪声（IEC 61000-4-6），验证通信误码率-9，无虚假故障上报</p><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-05</p><h2 id="modbus协议" tabindex="-1">Modbus协议 <a class="header-anchor" href="#modbus协议" aria-label="Permalink to &quot;Modbus协议&quot;">​</a></h2><p>核心概念▼</p><h4 id="modbus-rtu" tabindex="-1">Modbus RTU <a class="header-anchor" href="#modbus-rtu" aria-label="Permalink to &quot;Modbus RTU&quot;">​</a></h4><p>基于串行链路（RS-485/RS-232），二进制编码，CRC16校验。帧格式：从站地址(1B) + 功能码(1B) + 数据(NB) + CRC(2B)。通信模式为主从式，仅主站发起请求。波特率通常9600~115200bps。</p><h4 id="modbus-tcp" tabindex="-1">Modbus TCP <a class="header-anchor" href="#modbus-tcp" aria-label="Permalink to &quot;Modbus TCP&quot;">​</a></h4><p>基于TCP/IP，以太网传输。在RTU帧基础上增加MBAP头（事务ID+协议ID+长度+单元ID），无CRC（TCP已有校验）。默认端口502。支持多连接，可实现更高速率。</p><h4 id="寄存器映射" tabindex="-1">寄存器映射 <a class="header-anchor" href="#寄存器映射" aria-label="Permalink to &quot;寄存器映射&quot;">​</a></h4><p>4种数据类型：线圈(0x，读写1bit)、离散输入(1x，只读1bit)、保持寄存器(4x，读写16bit)、输入寄存器(3x，只读16bit)。地址范围0~65535。电机参数通常映射到保持寄存器。</p><h4 id="crc校验" tabindex="-1">CRC校验 <a class="header-anchor" href="#crc校验" aria-label="Permalink to &quot;CRC校验&quot;">​</a></h4><p>RTU模式使用CRC-16/MODBUS：多项式0x8005，初始值0xFFFF，结果异或0x0000。校验范围从从站地址到数据末尾。CRC低字节先发（小端序）。TCP模式由TCP层保证数据完整性，无需CRC。</p><p>电机控制关联：Modbus是变频器/伺服驱动器最通用的配置和监控协议。参数读写（PID增益、额定值）、运行控制（启停/方向）、状态监控（电流/转速/温度）均通过寄存器映射实现。</p><p>𝟗关键公式▼</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>N</mi><mrow><mi>b</mi><mi>i</mi><mi>t</mi><mi>s</mi></mrow></msub><msub><mi>f</mi><mrow><mi>b</mi><mi>a</mi><mi>u</mi><mi>d</mi></mrow></msub></mfrac></mrow><annotation encoding="application/x-tex">T_{frame} = \\frac{N_{bits}}{f_{baud}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2408em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ba</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">bi</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>RTU帧传输时间。N_bits = (1+8+1+1)<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span>字节数。9600bps下1字节约1.15ms，典型帧(8字节数据)约12ms。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>CRC-16</mtext><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msup><mi>x</mi><mn>16</mn></msup><mo>⊕</mo><msub><mi>d</mi><mi>i</mi></msub><mspace></mspace><mspace width="1em"></mspace><mo stretchy="false">(</mo><mrow><mi mathvariant="normal">m</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">d</mi></mrow><mspace width="0.3333em"></mspace><mi>g</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\text{CRC-16} = \\sum_{i} x^{16} \\oplus d_i \\pmod{g(x)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">CRC-16</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3277em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">16</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊕</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace allowbreak"></span><span class="mspace" style="margin-right:1em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord mathrm">mod</span></span></span><span class="mspace" style="margin-right:0.3333em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">))</span></span></span></span></span><p>CRC多项式 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>g</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><msup><mi>x</mi><mn>16</mn></msup><mo>+</mo><msup><mi>x</mi><mn>15</mn></msup><mo>+</mo><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">g(x)=x^{16}+x^{15}+x^2+1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">16</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">15</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。实际用查表法实现，256项查找表可一次处理1字节。</p><p>练习题 (2)▼</p><p>简单Modbus RTU帧格式是什么？CRC校验的原理和字节序？查看参考参考解答</p><p><strong>RTU帧格式：</strong></p><p>| 起始静默(3.5字符) | 从站地址(1B) | 功能码(1B) | 数据(NB) | CRC低(1B) | CRC高(1B) | 结束静默(3.5字符) |</p><p><strong>CRC校验原理：</strong></p><ol><li><p>预置CRC寄存器为0xFFFF</p></li><li><p>将帧的第一个字节与CRC寄存器低8位异或</p></li><li><p>CRC寄存器右移1位，若移出位为1则与0xA001异或</p></li><li><p>重复步骤3共8次</p></li><li><p>处理下一个字节，回到步骤2</p></li><li><p>所有字节处理完后，CRC寄存器即为校验值</p></li></ol><p>**字节序：**CRC低字节先发，高字节后发（小端序）。这是Modbus RTU与一般习惯（大端序）不同的地方，容易出错。</p><p>**3.5字符静默：**用于帧分隔。9600bps下3.5字符约4ms。帧内字符间隔不得超过1.5字符，否则视为新帧。</p><p>自评：掌握部分未掌握 中等如何将电机驱动器的运行参数映射到Modbus寄存器？设计一个包含转速设定、电流反馈、故障码的寄存器映射表。查看参考参考解答</p><p><strong>寄存器映射设计：</strong></p><p><strong>保持寄存器(4x) - 可读写：</strong></p><p>| 地址 | 名称 | 数据类型 | 缩放 | 说明 |</p><p>| 40001 | 运行命令 | UINT16 | - | bit0:启停, bit1:方向, bit2:故障复位 |</p><p>| 40002 | 转速设定 | INT16 | 1rpm/LSB | 范围-3000~+3000rpm |</p><p>| 40003 | 加速时间 | UINT16 | 1ms/LSB | 0~60000ms |</p><p>| 40004 | 减速时间 | UINT16 | 1ms/LSB | 0~60000ms |</p><p><strong>输入寄存器(3x) - 只读：</strong></p><p>| 地址 | 名称 | 数据类型 | 缩放 | 说明 |</p><p>| 30001 | 实际转速 | INT16 | 1rpm/LSB | 带符号 |</p><p>| 30002 | U相电流 | INT16 | 0.01A/LSB | -327.68~+327.67A |</p><p>| 30003 | V相电流 | INT16 | 0.01A/LSB | 同上 |</p><p>| 30004 | 母线电压 | UINT16 | 0.1V/LSB | 0~6553.5V |</p><p>| 30005 | 故障码 | UINT16 | - | bit0:过流, bit1:过压, bit2:过温, bit3:编码器 |</p><p>| 30006 | 驱动器状态 | UINT16 | - | 0:待机, 1:运行, 2:故障 |</p><p>**设计原则：**整数缩放避免浮点、连续地址便于批量读取、状态与控制分离、故障码位域便于快速判断。</p><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-06</p><h2 id="ethercat" tabindex="-1">EtherCAT <a class="header-anchor" href="#ethercat" aria-label="Permalink to &quot;EtherCAT&quot;">​</a></h2><p>核心概念▼</p><h4 id="分布式时钟-dc" tabindex="-1">分布式时钟(DC) <a class="header-anchor" href="#分布式时钟-dc" aria-label="Permalink to &quot;分布式时钟(DC)&quot;">​</a></h4><p>所有从站共享同一时间基准，同步精度</p><h4 id="从站配置" tabindex="-1">从站配置 <a class="header-anchor" href="#从站配置" aria-label="Permalink to &quot;从站配置&quot;">​</a></h4><p>ESI（EtherCAT Slave Information）描述从站设备：同步管理器(SyncManager)、PDO映射、FMMU配置。ESI文件导入主站后自动生成配置。从站ESC（EtherCAT Slave Controller）专用芯片（如ET1100/AX58100）处理协议。</p><h4 id="实时通信原理" tabindex="-1">实时通信原理 <a class="header-anchor" href="#实时通信原理" aria-label="Permalink to &quot;实时通信原理&quot;">​</a></h4><p>&quot;On the fly&quot;处理：以太网帧经过每个从站时，从站硬件在帧通过的同时读写数据，无需接收完整帧再转发。帧传输延迟仅数十纳秒/从站。一个以太网帧可寻址所有从站，利用率&gt;90%。</p><h4 id="通信周期" tabindex="-1">通信周期 <a class="header-anchor" href="#通信周期" aria-label="Permalink to &quot;通信周期&quot;">​</a></h4><p>典型周期125us~1ms。125us周期下可控制100+个伺服轴。周期抖动</p><p>电机控制关联：EtherCAT是高端多轴伺服系统的标准通信协议。分布式时钟确保所有轴同步运行，125us通信周期满足高速运动控制需求。CiA 402驱动器规范定义了标准化的伺服控制命令集。</p><p>𝟗关键公式▼</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>T</mi><mrow><mi>c</mi><mi>y</mi><mi>c</mi><mi>l</mi><mi>e</mi></mrow></msub><mo>=</mo><msub><mi>T</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>+</mo><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub><mo>+</mo><msub><mi>T</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>c</mi><mi>e</mi><mi>s</mi><mi>s</mi></mrow></msub><mo>+</mo><msub><mi>T</mi><mrow><mi>m</mi><mi>a</mi><mi>r</mi><mi>g</mi><mi>i</mi><mi>n</mi></mrow></msub></mrow><annotation encoding="application/x-tex">T_{cycle} = T_{prop} + T_{frame} + T_{process} + T_{margin}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">cy</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">ocess</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">in</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span></span><p>EtherCAT通信周期。T_prop为总传播延迟（~50ns/从站），T_frame为帧传输时间，T_process为从站处理时间。100个从站125us周期完全可行。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>T</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><msub><mi>N</mi><mrow><mi>s</mi><mi>l</mi><mi>a</mi><mi>v</mi><mi>e</mi><mi>s</mi></mrow></msub><mo>×</mo><msub><mi>t</mi><mrow><mi>d</mi><mi>e</mi><mi>l</mi><mi>a</mi><mi>y</mi><mi mathvariant="normal">_</mi><mi>p</mi><mi>e</mi><mi>r</mi><mi mathvariant="normal">_</mi><mi>s</mi><mi>l</mi><mi>a</mi><mi>v</mi><mi>e</mi></mrow></msub><mo>+</mo><mfrac><msub><mi>L</mi><mrow><mi>c</mi><mi>a</mi><mi>b</mi><mi>l</mi><mi>e</mi></mrow></msub><msub><mi>v</mi><mrow><mi>s</mi><mi>i</mi><mi>g</mi><mi>n</mi><mi>a</mi><mi>l</mi></mrow></msub></mfrac></mrow><annotation encoding="application/x-tex">T_{prop} = N_{slaves} \\times t_{delay\\_per\\_slave} + \\frac{L_{cable}}{v_{signal}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">es</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9821em;vertical-align:-0.367em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span><span class="mord mtight" style="margin-right:0.0278em;">_</span><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mtight" style="margin-right:0.0278em;">_</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.367em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3324em;vertical-align:-0.9721em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">na</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">ab</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>传播延迟。每从站硬件延迟约50~100ns，电缆延迟5ns/m。100个从站+100m电缆：T_prop≈10us+0.5us=10.5us。</p><p>练习题 (2)▼</p><p>简单EtherCAT如何实现确定性实时通信？分布式时钟的同步原理是什么？查看参考参考解答</p><p><strong>确定性实时通信：</strong></p><ol><li><p>**On-the-fly处理：**以太网帧经过从站时，ESC硬件在帧通过的同时读写数据，无需接收-处理-转发，延迟仅硬件级（数十纳秒）</p></li><li><p>**确定性延迟：**帧经过每个从站的延迟是固定的（由ESC硬件决定），不随数据内容变化</p></li><li><p>**主站调度：**主站精确控制帧发送时间，从站根据DC时钟在精确时刻锁存输出/采样输入</p></li><li><p>**无冲突：**全双工以太网+主站轮询，无CSMA/CD冲突</p></li></ol><p><strong>分布式时钟同步原理：</strong></p><ol><li><p>主站选择一个从站作为参考时钟（通常第一个DC从站）</p></li><li><p>主站发送带时间戳的帧，测量到每个从站的传播延迟</p></li><li><p>每个从站计算本地时钟与参考时钟的偏移量</p></li><li><p>从站通过锁相环(PLL)持续调整本地时钟跟踪参考时钟</p></li><li><p>同步精度自评：掌握部分未掌握 中等计算一个8轴伺服系统的EtherCAT通信周期。每个从站PDO数据32字节（16B入+16B出），帧开销14+4+2字节，传播延迟50ns/从站，处理时间20us。查看参考参考解答</p></li></ol><p><strong>计算过程：</strong></p><ol><li>**帧数据量：**以太网头14B + EtherCAT头(2B) + 数据区 + FCS 4B</li></ol><p>数据区 = 8从站 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span> 32B = 256B + 每个子报文头10B <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">×</span></span></span></span> 8 = 80B = 336B</p><p>总帧 = 14 + 2 + 336 + 4 = 356B = 2848位</p><ol start="2"><li><p><strong>帧传输时间：</strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>a</mi><mi>m</mi><mi>e</mi></mrow></msub><mo>=</mo><mn>2848</mn><mi mathvariant="normal">/</mi><mn>100</mn><mtext>Mbps</mtext><mo>=</mo><mn>28.48</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T_{frame} = 2848/100\\text{Mbps} = 28.48\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">2848/100</span><span class="mord text"><span class="mord">Mbps</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">28.48</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span></p></li><li><p><strong>传播延迟：</strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><mn>8</mn><mo>×</mo><mn>50</mn><mtext>ns</mtext><mo>=</mo><mn>0.4</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T_{prop} = 8 \\times 50\\text{ns} = 0.4\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">50</span><span class="mord text"><span class="mord">ns</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">0.4</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span>（可忽略）</p></li><li><p><strong>从站处理时间：</strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>c</mi><mi>e</mi><mi>s</mi><mi>s</mi></mrow></msub><mo>=</mo><mn>20</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T_{process} = 20\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">ocess</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">20</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span></p></li><li><p><strong>最小周期：</strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mrow><mi>c</mi><mi>y</mi><mi>c</mi><mi>l</mi><mi>e</mi></mrow></msub><mo>=</mo><mn>0.4</mn><mo>+</mo><mn>28.48</mn><mo>+</mo><mn>20</mn><mo>+</mo><mn>5</mn><mo stretchy="false">(</mo><mtext>裕量</mtext><mo stretchy="false">)</mo><mo>≈</mo><mn>54</mn><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">T_{cycle} = 0.4 + 28.48 + 20 + 5(\\text{裕量}) \\approx 54\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">cy</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">28.48</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">5</span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">裕量</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">54</span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span></p></li></ol><p><strong>实际周期选择：</strong></p><ul><li><p>125us周期：裕量充足，留70us给应用计算</p></li><li><p>250us周期：更稳定，适合大多数伺服应用</p></li><li><p>1ms周期：适合非伺服应用（I/O、变频器）</p></li></ul><p>8轴伺服系统推荐250us周期，通信带宽占用约22%。</p><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-07</p><h2 id="协议对比选型" tabindex="-1">协议对比选型 <a class="header-anchor" href="#协议对比选型" aria-label="Permalink to &quot;协议对比选型&quot;">​</a></h2><p>核心概念▼</p><h4 id="can-can-fd" tabindex="-1">CAN/CAN-FD <a class="header-anchor" href="#can-can-fd" aria-label="Permalink to &quot;CAN/CAN-FD&quot;">​</a></h4><p>优势：成本低、可靠性高、抗干扰强、多主仲裁。劣势：带宽有限（1Mbps/5Mbps）、节点数受限（110个）、距离受限（1Mbps时40m）。适用：汽车、工业自动化中低速场景。</p><h4 id="modbus-rtu-tcp" tabindex="-1">Modbus RTU/TCP <a class="header-anchor" href="#modbus-rtu-tcp" aria-label="Permalink to &quot;Modbus RTU/TCP&quot;">​</a></h4><p>优势：简单、开放、广泛支持、成本低。劣势：主从式无仲裁、RTU速率低、无确定性实时、TCP延迟不确定。适用：变频器参数配置、仪表数据采集、简单监控系统。</p><h4 id="ethercat-1" tabindex="-1">EtherCAT <a class="header-anchor" href="#ethercat-1" aria-label="Permalink to &quot;EtherCAT&quot;">​</a></h4><p>优势：确定性实时（</p><h4 id="profinet" tabindex="-1">PROFINET <a class="header-anchor" href="#profinet" aria-label="Permalink to &quot;PROFINET&quot;">​</a></h4><p>优势：与PROFIBUS生态兼容、IRT模式实时性高、诊断功能丰富。劣势：协议复杂、开发门槛高、授权费用。适用：PLC集成系统、过程自动化、工厂自动化。</p><p>电机控制选型决策：单轴/低成本选CAN；参数配置/监控选Modbus；多轴高速伺服选EtherCAT；PLC集成选PROFINET。实际项目常组合使用：EtherCAT做实时控制+Modbus做参数配置。</p><p>练习题 (2)▼</p><p>简单何时选CAN？何时选EtherCAT？画出简单的选型决策树。查看参考参考解答</p><p><strong>选型决策树：</strong></p><ol><li><strong>通信周期需求？</strong></li></ol><ul><li><p>≥1ms → CAN或Modbus</p></li><li><p>100us~1ms → CAN-FD或EtherCAT</p></li><li><p>8轴 → EtherCAT</p></li></ul><ol start="3"><li><strong>同步精度？</strong></li></ol><ul><li><p>不要求 → Modbus</p></li><li><p>自评：掌握部分未掌握 中等一个6轴机器人控制器需要选择通信协议。要求：通信周期250us，轴间同步精度查看参考参考解答</p></li></ul><p>**需求分析：**6轴 + 250us周期 + 自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-08</p><h2 id="autosar架构" tabindex="-1">AUTOSAR架构 <a class="header-anchor" href="#autosar架构" aria-label="Permalink to &quot;AUTOSAR架构&quot;">​</a></h2><p>核心概念▼</p><h4 id="classic分层结构" tabindex="-1">Classic分层结构 <a class="header-anchor" href="#classic分层结构" aria-label="Permalink to &quot;Classic分层结构&quot;">​</a></h4><p>三层架构：应用层(SWC) → 运行环境(RTE) → 基础软件(BSW)。BSW细分为：服务层、ECU抽象层、MCAL（微控制器抽象层）。RTE是SWC与BSW之间的标准接口，实现软件组件的独立开发。</p><h4 id="swc设计" tabindex="-1">SWC设计 <a class="header-anchor" href="#swc设计" aria-label="Permalink to &quot;SWC设计&quot;">​</a></h4><p>软件组件(SWC)是AUTOSAR应用的基本单元，通过端口(Port)通信。端口类型：发送者-接收者(S/R)用于数据传递，客户端-服务器(C/S)用于操作调用。SWC内部实现行为：Runnable Entity，由RTE事件触发。</p><h4 id="mcal" tabindex="-1">MCAL <a class="header-anchor" href="#mcal" aria-label="Permalink to &quot;MCAL&quot;">​</a></h4><p>微控制器抽象层直接操作硬件寄存器，提供标准化API。包含：ADC驱动、PWM驱动、GPIO驱动、CAN驱动、SPI驱动、GPT驱动等。MCAL由芯片厂商提供，确保上层软件可移植。</p><h4 id="功能安全" tabindex="-1">功能安全 <a class="header-anchor" href="#功能安全" aria-label="Permalink to &quot;功能安全&quot;">​</a></h4><p>AUTOSAR支持ISO 26262功能安全：内存分区（MPU保护SWC间隔离）、程序流监控、端到端(E2E)通信保护、看门狗管理、NvM数据完整性。ASIL-D级别需多重冗余和多样性设计。</p><p>电机控制关联：车规级电机控制器（EPS、ESP、eBooster）必须遵循AUTOSAR Classic架构。FOC算法封装为SWC，通过RTE与CAN通信栈、ADC驱动交互。功能安全要求ASIL-D时需双核锁步+软件冗余。</p><p>练习题 (2)▼</p><p>简单AUTOSAR Classic的分层结构是什么？SWC如何设计？查看参考参考解答</p><p><strong>Classic分层结构（自上而下）：</strong></p><ol><li><p>**应用层(SWC)：**实现具体功能逻辑，如FOC算法、状态机</p></li><li><p>**RTE（运行环境）：**SWC与BSW之间的通信中介，提供标准接口</p></li><li><p><strong>BSW（基础软件）：</strong></p></li></ol><ul><li><p>服务层：OS、COM、NvM、DEM、DET</p></li><li><p>ECU抽象层：内存抽象、通信抽象、I/O抽象</p></li><li><p>MCAL：ADC、PWM、GPIO、CAN、SPI等硬件驱动</p></li></ul><p><strong>SWC设计方法：</strong></p><ol><li><p>**组件划分：**按功能独立性和复用性划分，如FOC_SWC、CurrentSense_SWC、CANComm_SWC</p></li><li><p>**端口定义：**S/R端口传递数据（电流值、角度），C/S端口调用操作（启停、复位）</p></li><li><p>**Runnable设计：**由定时器事件触发（1ms电流环）、由数据接收事件触发（CAN指令到达）</p></li><li><p>**内部行为：**用状态机描述运行逻辑，通过RTE与外部交互</p></li></ol><p>自评：掌握部分未掌握 中等如何将一个FOC电机控制算法封装为AUTOSAR SWC？描述SWC的端口、Runnable和与其他SWC的交互。查看参考参考解答</p><p><strong>FOC_SWC设计：</strong></p><p><strong>端口定义：</strong></p><ul><li><p>P_CurrentFeedback (S/R, 接收)：Iu, Iv, Iw三相电流</p></li><li><p>P_AngleFeedback (S/R, 接收)：电角度θ</p></li><li><p>P_SpeedCommand (S/R, 接收)：目标转速</p></li><li><p>P_PwmDuty (S/R, 发送)：Ta, Tb, Tc占空比</p></li><li><p>P_Status (S/R, 发送)：运行状态、故障码</p></li><li><p>P_Control (C/S, 提供)：Start(), Stop(), ResetFault()</p></li></ul><p><strong>Runnable设计：</strong></p><ul><li><p>Run_CurrentLoop：由10kHz定时器事件触发，执行Clarke/Park变换、PI电流环、逆Park/SVPWM</p></li><li><p>Run_SpeedLoop：由1kHz定时器事件触发，执行速度PI、输出Iq_ref</p></li><li><p>Run_FaultCheck：由数据接收事件触发，检查过流/过压/过温</p></li></ul><p><strong>SWC交互：</strong></p><ul><li><p>CurrentSense_SWC → FOC_SWC：电流采样值</p></li><li><p>Encoder_SWC → FOC_SWC：角度/速度反馈</p></li><li><p>CANComm_SWC → FOC_SWC：远程指令</p></li><li><p>FOC_SWC → PwmGen_SWC：占空比输出</p></li><li><p>FOC_SWC → Diag_SWC：故障上报</p></li></ul><p>自评：掌握部分未掌握</p><p>完成所有练习后标记为已学习标记为已学习</p><p>COM-09</p><h2 id="工业通信phy" tabindex="-1">工业通信PHY <a class="header-anchor" href="#工业通信phy" aria-label="Permalink to &quot;工业通信PHY&quot;">​</a></h2><p>核心概念▼</p><h4 id="can-phy" tabindex="-1">CAN PHY <a class="header-anchor" href="#can-phy" aria-label="Permalink to &quot;CAN PHY&quot;">​</a></h4><p>CAN收发器（如TJA1050/SN65HVD230）将MCU的TX/RX信号转换为差分CANH/CANL。显性：CANH=3.5V, CANL=1.5V；隐性：CANH=CANL=2.5V。差分信号抗共模干扰。支持高速CAN（ISO 11898-2）和容错CAN（ISO 11898-3）。</p><h4 id="ethercat-phy" tabindex="-1">EtherCAT PHY <a class="header-anchor" href="#ethercat-phy" aria-label="Permalink to &quot;EtherCAT PHY&quot;">​</a></h4><p>标准以太网PHY（如KSZ8041/DP83848）+ESC芯片（ET1100/AX58100）。PHY提供MII/RMII接口连接ESC，ESC处理EtherCAT协议。需支持100Mbps全双工、自动协商、MDIO管理接口。双端口PHY用于环型拓扑。</p><h4 id="隔离技术" tabindex="-1">隔离技术 <a class="header-anchor" href="#隔离技术" aria-label="Permalink to &quot;隔离技术&quot;">​</a></h4><p>数字隔离（磁耦/容耦）：速率高（&gt;150Mbps）、寿命长、无老化。光耦：成本低但速率受限（1~10Mbps）、CTR衰减。隔离电源：DC-DC隔离电源为总线侧供电。隔离耐压通常2500Vrms~5000Vrms。</p><h4 id="esd防护" tabindex="-1">ESD防护 <a class="header-anchor" href="#esd防护" aria-label="Permalink to &quot;ESD防护&quot;">​</a></h4><p>TVS二极管保护总线引脚：CAN用双向TVS（如PESD2CAN），钳位电压</p><p>电机控制关联：电机驱动器工作在高dV/dt、大电流开关环境，EMI严重。通信PHY必须有隔离和ESD防护，否则CAN/EtherCAT通信会被干扰导致丢帧或误码。隔离是安全要求（高压母线与通信接口之间）。</p><p>练习题 (2)▼</p><p>简单为什么电机驱动器的通信接口需要隔离？ESD防护等级要求是什么？查看参考参考解答</p><p><strong>为什么需要隔离：</strong></p><ol><li><p>**安全：**电机驱动器母线电压可达数百伏（48V~800V），通信接口连接外部设备（PLC/HMI）。无隔离时故障电压可能通过通信线传导到外部，危及人身安全</p></li><li><p>**地环路消除：**多设备共地形成地环路，地电位差导致通信误码。隔离切断地环路</p></li><li><p>**共模抑制：**电机开关产生高dV/dt（&gt;10kV/us），通过寄生电容耦合到通信线。隔离提供高共模抑制能力</p></li><li><p>**法规要求：**IEC 61800-5-1要求驱动器通信接口满足加强绝缘或双重绝缘</p></li></ol><p><strong>ESD防护等级：</strong></p><ul><li><p>IEC 61000-4-2标准</p></li><li><p>工业级：接触放电±4kV（最低），±8kV（推荐）</p></li><li><p>空气放电：±8kV（最低），±15kV（推荐）</p></li><li><p>汽车级：±8kV接触，±15kV空气</p></li></ul><p>TVS选型：钳位电压低于收发器最大耐压，结电容不影响信号质量</p><p>自评：掌握部分未掌握 中等设计一个48V电机驱动器的CAN通信接口，包含收发器选型、隔离方案和ESD防护。画出接口电路框图。查看参考参考解答</p><p><strong>接口电路框图：</strong></p><p>MCU(CAN_TX/CAN_RX) → 数字隔离器(ISO7721) → CAN收发器(TJA1050) → TVS(PESD2CAN) → CANH/CANL总线</p><p><strong>各环节设计：</strong></p><ol><li><p>**数字隔离器 ISO7721：**双通道（正向TX+反向RX），速率150Mbps，隔离耐压5000Vrms，功耗约10mW/ch。替代传统光耦6N137（速率仅10Mbps）</p></li><li><p>**隔离电源：**DC-DC模块（B0505S-1W）为总线侧供电，5V输入5V输出1W，隔离3000VDC。或使用带集成电源的隔离器（如ISO7742+内部变压器的方案）</p></li><li><p>**CAN收发器 TJA1050：**高速CAN（1Mbps），SO8封装，显性/隐性电平符合ISO 11898-2。斜率控制模式可降低EMI</p></li><li><p>**ESD防护 PESD2CAN：**双向TVS，钳位电压40V，结电容自评：掌握部分未掌握</p></li></ol><p>完成所有练习后标记为已学习标记为已学习</p>',274)])])}const d=a(t,[["render",l]]);export{g as __pageData,d as default};
